# ==============================================================================

import torch
from transformers import AutoModelForSequenceClassification, AutoTokenizer
from peft import LoraConfig, get_peft_model, TaskType

def run_adapted_chatgpt_snippet():
    print("=" * 70)
    print("Session 3 - Task 5: Executing ChatGPT-Generated LoRA Implementation")
    print("=" * 70)

    model_name = "distilbert-base-uncased"
    tokenizer = AutoTokenizer.from_pretrained(model_name)
    model = AutoModelForSequenceClassification.from_pretrained(model_name, num_labels=2)

    # --------------------------------------------------------------------------
    # ADAPTATIONS MADE FOR LOCAL ENVIRONMENT:
    # 1. Target Modules: Changed from ["q_proj", "v_proj"] to ["q_lin", "v_lin"]
    #    because DistilBERT uses Linear attention layers named `q_lin` and `v_lin`.
    # 2. Task Type: Changed from TaskType.CAUSAL_LM (or string) to TaskType.SEQ_CLS
    #    so PEFT preserves the sequence classification head parameters as trainable.
    # 3. Dynamic Device: Replaced hardcoded `.to("cuda")` with torch.device check
    #    to ensure smooth execution on CPU or GPU without runtime device crash.
    # --------------------------------------------------------------------------
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    print(f"Active Device: {device}")

    config = LoraConfig(
        task_type=TaskType.SEQ_CLS,
        r=16,
        lora_alpha=32,
        target_modules=["q_lin", "v_lin"], # Corrected for DistilBERT
        lora_dropout=0.05,
        bias="none"
    )

    lora_model = get_peft_model(model, config)
    lora_model.to(device)

    print("\nSuccessfully initialized adapted model!")
    lora_model.print_trainable_parameters()

    # Test dummy inference forward pass
    sample_text = "This film was an absolute masterpiece with incredible acting."
    inputs = tokenizer(sample_text, return_tensors="pt").to(device)
    with torch.no_grad():
        outputs = lora_model(**inputs)
        logits = outputs.logits
        predicted_class = torch.argmax(logits, dim=1).item()

    print(f"\nInference Verification:")
    print(f"Sample Input    : \"{sample_text}\"")
    print(f"Logits Output   : {logits.tolist()}")
    print(f"Predicted Class : {predicted_class}")

    print("\n" + "=" * 70)
    print("Task 5 Completed Successfully!")
    print("=" * 70)

if __name__ == "__main__":
    run_adapted_chatgpt_snippet()
